/* Shared entry and exit: Dialog, AlertDialog, CommandPalette and QuickView animate with these. */
@layer kg.components {
  @keyframes kg-dialog-in {
    from {
      opacity: 0;
      transform: translateY(12px);
      box-shadow: 0 0 0 var(--kg-ink);
    }
  }

  @keyframes kg-dialog-out {
    to {
      opacity: 0;
      transform: translateY(6px);
    }
  }
}

"use client"

import {
  type DialogHTMLAttributes,
  forwardRef,
  type HTMLAttributes,
  type RefObject,
} from "react"
import { useComposedRefs } from "../lib/utils/compose-refs"
import { cx } from "../lib/utils/cx"
import {
  createModalClose,
  createModalTrigger,
  type ModalButtonProps,
  ModalCloseButton,
  ModalRoot,
  type ModalRootProps,
  useModalContext,
  useModalPart,
  useModalSurface,
} from "./modal"

export type DialogSize = "sm" | "md" | "lg" | "full"

/* A sheet set down on the page: it rises from flat and settles onto its offset. */
const contentClass = [
  "kg-dialog fixed inset-0 m-auto max-w-none overflow-hidden p-0 text-kg-fg bg-(--_dialog-bg,var(--kg-surface)) outline-none origin-[50%_100%] open:flex open:flex-col",
  "data-[state=open]:animate-[kg-dialog-in_var(--kg-duration-slow)_var(--kg-ease-out)]",
  "data-[state=closed]:pointer-events-none data-[state=closed]:animate-[kg-dialog-out_var(--kg-duration-fast)_var(--kg-ease-in)_forwards]",
  "backdrop:bg-kg-overlay backdrop:animate-[kg-fade-in_var(--kg-duration-base)_var(--kg-ease-out)]",
  "data-[state=closed]:backdrop:animate-[kg-fade-out_var(--kg-duration-fast)_var(--kg-ease-in)_forwards]",
]

const sheet =
  "h-fit max-h-[calc(100dvh-var(--kg-space)*8)] border-2 border-kg-ink rounded-kg-xl shadow-kg-lg"

/* Set --_dialog-bg on the content to replace the surface colour. */
const sizeClass: Record<DialogSize, string> = {
  sm: `${sheet} w-[min(24rem,calc(100%-var(--kg-space)*8))]`,
  md: `${sheet} w-[min(32rem,calc(100%-var(--kg-space)*8))]`,
  lg: `${sheet} w-[min(44rem,calc(100%-var(--kg-space)*8))]`,
  full: "size-full max-h-none border-0",
}

const bodyClass =
  "kg-dialog__body min-h-0 flex-[1_1_auto] overflow-y-auto overscroll-contain px-6 py-4 text-kg-base leading-[1.55]"

const footerClass = [
  "kg-dialog__footer flex shrink-0 flex-wrap justify-end gap-2 px-6 pt-4 pb-6",
  String.raw`[.kg-dialog\_\_header+&]:pt-6`,
  "max-[30rem]:flex-col-reverse max-[30rem]:*:w-full",
]

export interface DialogProps extends ModalRootProps {}

/** Owns the open state. Renders no element of its own. */
export const Dialog = (props: DialogProps) => <ModalRoot {...props} />

Dialog.displayName = "Dialog"

export interface DialogTriggerProps extends ModalButtonProps {}

export const DialogTrigger = createModalTrigger("DialogTrigger")

export interface DialogCloseProps extends ModalButtonProps {}

export const DialogClose = createModalClose("DialogClose")

export interface DialogContentProps extends Omit<
  DialogHTMLAttributes<HTMLDialogElement>,
  "open"
> {
  size?: DialogSize
  /** Close when the backdrop is clicked. Escape always closes. */
  dismissible?: boolean
  /** Receives focus on open. Defaults to the first focusable element inside. */
  initialFocus?: RefObject<HTMLElement | null>
  /** Receives focus on close. Defaults to the element that was focused before opening. */
  finalFocus?: RefObject<HTMLElement | null>
  /** Show the built-in close button in the corner. */
  closeButton?: boolean
  /** Accessible name of the built-in close button. */
  closeLabel?: string
}

export const DialogContent = forwardRef<HTMLDialogElement, DialogContentProps>(
  (
    {
      size = "md",
      dismissible = true,
      initialFocus,
      finalFocus,
      closeButton = true,
      closeLabel = "Close",
      onCancel,
      onClose,
      onPointerDown,
      onClick,
      "aria-labelledby": labelledBy,
      "aria-describedby": describedBy,
      className,
      children,
      ...props
    },
    forwardedRef,
  ) => {
    const context = useModalContext("DialogContent")
    const surface = useModalSurface(context, {
      dismissible,
      initialFocus,
      finalFocus,
      onCancel,
      onClose,
      onPointerDown,
      onClick,
      "aria-labelledby": labelledBy,
      "aria-describedby": describedBy,
    })
    const ref = useComposedRefs(surface.ref, forwardedRef)
    if (!surface.present) return null

    return (
      <dialog
        ref={ref}
        className={cx(contentClass, sizeClass[size] ?? sizeClass.md, className)}
        data-size={size}
        data-state={surface.state}
        {...props}
        {...surface.props}
      >
        {children}
        {closeButton && (
          <div className="absolute end-3 top-3 z-1">
            <ModalCloseButton label={closeLabel} className="kg-dialog__close" />
          </div>
        )}
      </dialog>
    )
  },
)

DialogContent.displayName = "DialogContent"

export interface DialogHeaderProps extends HTMLAttributes<HTMLDivElement> {}

export const DialogHeader = forwardRef<HTMLDivElement, DialogHeaderProps>(
  ({ className, ...props }, ref) => (
    <div
      ref={ref}
      className={cx("kg-dialog__header grid shrink-0 gap-1.5 ps-6 pe-12 pt-6", className)}
      {...props}
    />
  ),
)

DialogHeader.displayName = "DialogHeader"

export interface DialogTitleProps extends HTMLAttributes<HTMLHeadingElement> {}

export const DialogTitle = forwardRef<HTMLHeadingElement, DialogTitleProps>(
  ({ className, ...props }, ref) => {
    const context = useModalContext("DialogTitle")
    useModalPart(context.setHasTitle)
    return (
      <h2
        ref={ref}
        className={cx("kg-dialog__title m-0 text-kg-lg leading-[1.3] font-semibold tracking-[-0.015em] text-kg-fg", className)}
        {...props}
        id={context.titleId}
      />
    )
  },
)

DialogTitle.displayName = "DialogTitle"

export interface DialogDescriptionProps extends HTMLAttributes<HTMLParagraphElement> {}

export const DialogDescription = forwardRef<
  HTMLParagraphElement,
  DialogDescriptionProps
>(({ className, ...props }, ref) => {
  const context = useModalContext("DialogDescription")
  useModalPart(context.setHasDescription)
  return (
    <p
      ref={ref}
      className={cx(
        "kg-dialog__description m-0 text-kg-base leading-[1.55] text-kg-fg-muted",
        className,
      )}
      {...props}
      id={context.descriptionId}
    />
  )
})

DialogDescription.displayName = "DialogDescription"

export interface DialogBodyProps extends HTMLAttributes<HTMLDivElement> {}

/** The scrolling region between header and footer. */
export const DialogBody = forwardRef<HTMLDivElement, DialogBodyProps>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cx(bodyClass, className)} {...props} />
  ),
)

DialogBody.displayName = "DialogBody"

export interface DialogFooterProps extends HTMLAttributes<HTMLDivElement> {}

export const DialogFooter = forwardRef<HTMLDivElement, DialogFooterProps>(
  ({ className, ...props }, ref) => (
    <div ref={ref} className={cx(footerClass, className)} {...props} />
  ),
)

DialogFooter.displayName = "DialogFooter"

const TABBABLE = [
  "a[href]",
  "button:not([disabled])",
  "input:not([disabled]):not([type='hidden'])",
  "select:not([disabled])",
  "textarea:not([disabled])",
  "summary",
  "iframe",
  "audio[controls]",
  "video[controls]",
  "[contenteditable]:not([contenteditable='false'])",
  "[tabindex]",
].join(",")

/** Keyboard-reachable descendants of `root`, in tree order. */
export const getTabbable = (root: HTMLElement): HTMLElement[] =>
  Array.from(root.querySelectorAll<HTMLElement>(TABBABLE)).filter(
    (element) => element.tabIndex >= 0 && !element.closest("[hidden], [inert]"),
  )

/**
 * Moves focus into a surface that just opened: the preferred element, else the first tabbable
 * one not matching `skip` (so a corner close button isn't the default), else the surface itself.
 */
export const focusInto = (
  root: HTMLElement,
  preferred?: HTMLElement | null,
  skip?: string,
): void => {
  if (preferred) {
    preferred.focus()
    return
  }
  const candidates = getTabbable(root)
  const target =
    candidates.find((element) => !skip || !element.matches(skip)) ??
    candidates[0] ??
    root
  target.focus()
}

/** True when focus is about to be lost: on the body, nowhere, or inside a closing surface. */
export const shouldReclaimFocus = (surface: HTMLElement | null): boolean => {
  const active = document.activeElement
  return !active || active === document.body || (surface?.contains(active) ?? false)
}

"use client"

import {
  type ButtonHTMLAttributes,
  createContext,
  type DialogHTMLAttributes,
  type Dispatch,
  forwardRef,
  type MouseEvent as ReactMouseEvent,
  type ReactNode,
  type RefObject,
  type SetStateAction,
  useContext,
  useId,
  useMemo,
  useRef,
  useState,
} from "react"
import { useControllableState } from "../lib/hooks/use-controllable-state"
import { useDismiss } from "../lib/hooks/use-dismiss"
import { useIsomorphicLayoutEffect } from "../lib/hooks/use-isomorphic-layout-effect"
import { usePresence } from "../lib/hooks/use-presence"
import { useScrollLock } from "../lib/hooks/use-scroll-lock"
import { Slot } from "../lib/primitives/slot"
import { useComposedRefs } from "../lib/utils/compose-refs"
import { IconButton } from "../icon-button/icon-button"
import { focusInto, shouldReclaimFocus } from "./focus"

/*
 * Shared machinery for every surface built on the native <dialog> element (Dialog, Drawer, and
 * the commerce QuickView / gallery built on them). Not part of the public API.
 */

export interface ModalContextValue {
  open: boolean
  setOpen: (open: boolean) => void
  modal: boolean
  triggerRef: RefObject<HTMLElement | null>
  contentId: string
  titleId: string
  descriptionId: string
  hasTitle: boolean
  hasDescription: boolean
  setHasTitle: Dispatch<SetStateAction<boolean>>
  setHasDescription: Dispatch<SetStateAction<boolean>>
}

export const ModalContext = createContext<ModalContextValue | null>(null)

export const useModalContext = (part: string): ModalContextValue => {
  const context = useContext(ModalContext)
  if (!context)
    throw new Error(`<${part}> must be rendered inside its <Dialog> or <Drawer>.`)
  return context
}

export interface ModalRootProps {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Blocks and inerts the page and locks its scroll. Non-modal surfaces leave the page live. */
  modal?: boolean
  children?: ReactNode
}

export const ModalRoot = ({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  modal = true,
  children,
}: ModalRootProps) => {
  const [open, setOpen] = useControllableState({
    value: openProp,
    defaultValue: defaultOpen,
    onChange: onOpenChange,
  })
  const triggerRef = useRef<HTMLElement | null>(null)
  const id = useId()
  const [hasTitle, setHasTitle] = useState(false)
  const [hasDescription, setHasDescription] = useState(false)

  const value = useMemo<ModalContextValue>(
    () => ({
      open,
      setOpen,
      modal,
      triggerRef,
      contentId: `${id}-content`,
      titleId: `${id}-title`,
      descriptionId: `${id}-description`,
      hasTitle,
      hasDescription,
      setHasTitle,
      setHasDescription,
    }),
    [open, setOpen, modal, id, hasTitle, hasDescription],
  )

  return <ModalContext.Provider value={value}>{children}</ModalContext.Provider>
}

/** Lets a title or description wire `aria-labelledby` / `aria-describedby` only while it exists. */
export const useModalPart = (register: Dispatch<SetStateAction<boolean>>): void => {
  useIsomorphicLayoutEffect(() => {
    register(true)
    return () => register(false)
  }, [register])
}

export interface ModalButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  /** Merge behaviour onto the single child element (e.g. a kitgrid Button) instead. */
  asChild?: boolean
}

export const createModalTrigger = (displayName: string) => {
  const Trigger = forwardRef<HTMLButtonElement, ModalButtonProps>(
    ({ asChild = false, onClick, ...props }, forwardedRef) => {
      const context = useModalContext(displayName)
      const ref = useComposedRefs(context.triggerRef, forwardedRef)
      const shared = {
        ref,
        "aria-haspopup": "dialog" as const,
        "aria-expanded": context.open,
        "aria-controls": context.open ? context.contentId : undefined,
        "data-state": context.open ? "open" : "closed",
        onClick: (event: ReactMouseEvent<HTMLButtonElement>) => {
          onClick?.(event)
          if (!event.defaultPrevented) context.setOpen(!context.open)
        },
      }
      if (asChild) return <Slot {...shared} {...props} />
      return <button type="button" {...shared} {...props} />
    },
  )
  Trigger.displayName = displayName
  return Trigger
}

export const createModalClose = (displayName: string) => {
  const Close = forwardRef<HTMLButtonElement, ModalButtonProps>(
    ({ asChild = false, onClick, ...props }, ref) => {
      const context = useModalContext(displayName)
      const handleClick = (event: ReactMouseEvent<HTMLButtonElement>) => {
        onClick?.(event)
        if (!event.defaultPrevented) context.setOpen(false)
      }
      if (asChild) return <Slot ref={ref} onClick={handleClick} {...props} />
      return <button ref={ref} type="button" onClick={handleClick} {...props} />
    },
  )
  Close.displayName = displayName
  return Close
}

export const MODAL_CLOSE_ATTRIBUTE = "data-kg-modal-close"

const CloseIcon = () => (
  <svg
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    strokeWidth="2"
    aria-hidden="true"
  >
    <path d="M18 6 6 18M6 6l12 12" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
)

export const ModalCloseButton = ({
  label,
  className,
}: {
  label: string
  className: string
}) => {
  const context = useModalContext("ModalCloseButton")
  return (
    <IconButton
      label={label}
      icon={<CloseIcon />}
      size="sm"
      className={className}
      {...{ [MODAL_CLOSE_ATTRIBUTE]: "" }}
      onClick={() => context.setOpen(false)}
    />
  )
}

type DialogHandlers = Pick<
  DialogHTMLAttributes<HTMLDialogElement>,
  | "onCancel"
  | "onClose"
  | "onPointerDown"
  | "onClick"
  | "aria-labelledby"
  | "aria-describedby"
>

export interface ModalSurfaceOptions extends DialogHandlers {
  /** Close on a backdrop click. Escape always closes, as the dialog pattern requires. */
  dismissible: boolean
  initialFocus?: RefObject<HTMLElement | null> | undefined
  finalFocus?: RefObject<HTMLElement | null> | undefined
}

const isOutside = (
  node: HTMLElement,
  point: { clientX: number; clientY: number },
): boolean => {
  const rect = node.getBoundingClientRect()
  return (
    point.clientX < rect.left ||
    point.clientX > rect.right ||
    point.clientY < rect.top ||
    point.clientY > rect.bottom
  )
}

/**
 * Drives a native <dialog>: showModal() on open, exit animation before close(), scroll lock,
 * Escape through the `cancel` event, backdrop dismissal, initial focus and focus return.
 */
export const useModalSurface = (
  context: ModalContextValue,
  options: ModalSurfaceOptions,
) => {
  const { open, setOpen, modal, triggerRef } = context
  const presence = usePresence<HTMLDialogElement>(open)
  const { ref, present } = presence
  const pressedBackdrop = useRef(false)
  const { initialFocus, finalFocus, dismissible } = options
  useScrollLock(present && modal)

  useIsomorphicLayoutEffect(() => {
    const node = ref.current
    if (!present || !node) return
    const active = document.activeElement
    const returnTo =
      active instanceof HTMLElement && active !== document.body ? active : null
    if (!node.open) {
      if (modal) node.showModal()
      else node.show()
    }
    focusInto(node, initialFocus?.current, `[${MODAL_CLOSE_ATTRIBUTE}]`)
    return () => {
      // Decided before close(): browsers restore focus themselves, which would mask `finalFocus`.
      const reclaim = shouldReclaimFocus(node)
      if (node.open) node.close()
      if (!reclaim) return
      const target =
        finalFocus?.current ?? (returnTo?.isConnected ? returnTo : triggerRef.current)
      target?.focus()
    }
  }, [present])

  // Native non-modal dialogs ignore Escape and outside clicks, so those come from useDismiss.
  useDismiss({
    enabled: open && !modal,
    refs: [ref, triggerRef],
    outside: dismissible,
    onDismiss: () => setOpen(false),
  })

  const props: DialogHTMLAttributes<HTMLDialogElement> = {
    id: context.contentId,
    tabIndex: -1,
    "aria-labelledby":
      options["aria-labelledby"] ?? (context.hasTitle ? context.titleId : undefined),
    "aria-describedby":
      options["aria-describedby"] ??
      (context.hasDescription ? context.descriptionId : undefined),
    onCancel: (event) => {
      options.onCancel?.(event)
      const vetoed = event.defaultPrevented
      // Keep the element open so the exit animation can run; close() follows the state change.
      event.preventDefault()
      if (!vetoed) setOpen(false)
    },
    onClose: (event) => {
      options.onClose?.(event)
      // A close event queued by a StrictMode remount can land after the dialog reopened.
      if (!event.currentTarget.open) setOpen(false)
    },
    onPointerDown: (event) => {
      options.onPointerDown?.(event)
      pressedBackdrop.current =
        event.target === event.currentTarget && isOutside(event.currentTarget, event)
    },
    onClick: (event) => {
      options.onClick?.(event)
      const pressed = pressedBackdrop.current
      pressedBackdrop.current = false
      if (!dismissible || !modal || !pressed || event.defaultPrevented) return
      // Backdrop clicks target the <dialog> itself, outside its box. Requiring the press to start
      // there too keeps a text selection dragged out of the panel from closing it.
      if (
        event.target === event.currentTarget &&
        isOutside(event.currentTarget, event)
      ) {
        setOpen(false)
      }
    },
  }

  return { ...presence, props }
}
